using TutorFlow.Core.Academico;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal sealed class AfirmacionesDePerdida
{
    private const int PalabrasDeNegacion = 2;

    private static readonly HashSet<string> FormasDePerdida = new(StringComparer.Ordinal)
    {
        "perdi", "perdio", "perdiste", "perdieron", "perdido", "perdidos", "perdida", "perdidas"
    };

    private static readonly HashSet<string> Negaciones = new(StringComparer.Ordinal)
    {
        "no", "ni", "sin", "ningun", "ninguna"
    };

    private static readonly HashSet<string> Inasistencias = new(StringComparer.Ordinal)
    {
        "inasistencia", "inasistencias"
    };

    private readonly IReadOnlyList<AsignaturaCatalogo> _catalogo;

    public AfirmacionesDePerdida(IReadOnlyList<AsignaturaCatalogo> catalogo)
    {
        _catalogo = catalogo;
    }

    public bool SonVerificables(
        string respuesta,
        IReadOnlyCollection<string> idsAutorizados,
        DirectorioAcademico directorio,
        IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos) =>
        TramosDePersonas.Oraciones(respuesta)
            .SelectMany(oracion => TramosDePersonas.De(oracion, idsAutorizados, directorio))
            .All(tramo => TramoEsVerificable(tramo, resumenesLeidos));

    private bool TramoEsVerificable(TramoDePersona tramo, IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
    {
        var nombradas = AsignaturasNombradas(tramo.Tokens);
        if (nombradas.Count == 0 || !HayPerdidaNoNegada(tramo.Tokens))
        {
            return true;
        }

        return resumenesLeidos.TryGetValue(tramo.PersonaId, out var resumen)
            && ExigenciasPorAsignatura(tramo.Tokens, nombradas).All(exigencia => Cumple(exigencia, resumen));
    }

    private static bool HayPerdidaNoNegada(IReadOnlyList<TokenTexto> tokens) =>
        Enumerable.Range(0, tokens.Count).Any(indice => FormasDePerdida.Contains(tokens[indice].Valor) && !EstaNegada(tokens, indice));

    private static bool EstaNegada(IReadOnlyList<TokenTexto> tokens, int indice) =>
        Enumerable.Range(Math.Max(0, indice - PalabrasDeNegacion), Math.Min(PalabrasDeNegacion, indice))
            .Any(anterior => Negaciones.Contains(tokens[anterior].Valor));

    private List<AsignaturaNombrada> AsignaturasNombradas(IReadOnlyList<TokenTexto> tokens) =>
        [.. _catalogo
            .Select(asignatura => new AsignaturaNombrada(AmbitoPersonal.Clave(asignatura.Codigo), PrimeraAparicion(tokens, asignatura)))
            .Where(nombrada => nombrada.Indice >= 0)
            .OrderBy(nombrada => nombrada.Indice)];

    private static int PrimeraAparicion(IReadOnlyList<TokenTexto> tokens, AsignaturaCatalogo asignatura)
    {
        var apariciones = new[] { asignatura.Nombre, asignatura.Codigo }
            .Select(texto => TokenizadorTexto.BuscarSecuencia(tokens, TokenizadorTexto.Valores(texto)))
            .Where(indice => indice >= 0)
            .ToList();
        return apariciones.Count == 0 ? -1 : apariciones.Min();
    }

    private static IEnumerable<ExigenciaDeAsignatura> ExigenciasPorAsignatura(
        IReadOnlyList<TokenTexto> tokens,
        IReadOnlyList<AsignaturaNombrada> nombradas)
    {
        var inasistencias = Enumerable.Range(0, tokens.Count).Where(indice => Inasistencias.Contains(tokens[indice].Valor)).ToList();
        var antesDeLaPrimera = inasistencias.Any(indice => indice < nombradas[0].Indice);
        return nombradas.Select((nombrada, posicion) =>
        {
            var hasta = posicion + 1 < nombradas.Count ? nombradas[posicion + 1].Indice : int.MaxValue;
            var porInasistencia = antesDeLaPrimera || inasistencias.Any(indice => indice >= nombrada.Indice && indice < hasta);
            return new ExigenciaDeAsignatura(nombrada.Clave, porInasistencia);
        });
    }

    private static bool Cumple(ExigenciaDeAsignatura exigencia, ResumenEstudiante resumen)
    {
        var resultado = resumen.Asignaturas.FirstOrDefault(r => AmbitoPersonal.Clave(r.Asignatura.Codigo) == exigencia.Clave);
        return resultado is not null
            && (exigencia.PorInasistencia
                ? resultado.Estado == EstadoAsignatura.PerdidaPorInasistencia
                : resultado.Estado is EstadoAsignatura.Perdida or EstadoAsignatura.PerdidaPorInasistencia);
    }

    private sealed record AsignaturaNombrada(string Clave, int Indice);

    private sealed record ExigenciaDeAsignatura(string Clave, bool PorInasistencia);
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal sealed record TramoDePersona(string PersonaId, IReadOnlyList<TokenTexto> Tokens);

internal static partial class TramosDePersonas
{
    public static IEnumerable<string> Oraciones(string respuesta) =>
        CorteDeOracion().Split(respuesta).Where(oracion => !string.IsNullOrWhiteSpace(oracion));

    public static IReadOnlyList<TramoDePersona> De(
        string oracion,
        IReadOnlyCollection<string> idsAutorizados,
        DirectorioAcademico directorio)
    {
        var menciones = DetectorTerceros.MencionesDeAutorizados(oracion, idsAutorizados, directorio);
        if (menciones.Count == 0)
        {
            return [];
        }

        var tokens = TokenizadorTexto.Tokenizar(oracion);
        var primeraDeCualquiera = menciones[0].Inicio;
        return [.. menciones.GroupBy(mencion => mencion.Id)
            .Select(grupo => TramoDe(grupo.Key, grupo.First().Inicio, menciones, tokens, primeraDeCualquiera))];
    }

    private static TramoDePersona TramoDe(
        string personaId,
        int inicio,
        IReadOnlyList<MencionDeAutorizado> menciones,
        IReadOnlyList<TokenTexto> tokens,
        int primeraDeCualquiera)
    {
        var fin = menciones
            .Where(mencion => mencion.Id != personaId && mencion.Inicio > inicio)
            .Select(mencion => mencion.Inicio)
            .DefaultIfEmpty(int.MaxValue)
            .Min();
        var delTramo = tokens.Where(token => token.Inicio < primeraDeCualquiera || (token.Inicio >= inicio && token.Inicio < fin));
        return new TramoDePersona(personaId, [.. delTramo]);
    }

    [GeneratedRegex(@"\r?\n|(?<=[.!?;])(?=\s|$)", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex CorteDeOracion();
}
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

public sealed record AsignaturaCatalogo(string Codigo, string Nombre);

internal static class CatalogoAsignaturas
{
    public static IReadOnlyList<AsignaturaCatalogo> PorDefecto { get; } =
    [
        new("CAL-201", "Cálculo Integral"),
        new("POO-202", "Programación Orientada a Objetos"),
        new("BD-203", "Bases de Datos"),
        new("ING-204", "Inglés III"),
        new("CON-101", "Contabilidad"),
        new("MIC-102", "Microeconomía"),
        new("EST-103", "Estadística"),
        new("COM-104", "Comunicación Oral y Escrita")
    ];

    public static IReadOnlyList<string> CodigosNombrados(
        string pregunta,
        IReadOnlyList<AsignaturaCatalogo> catalogo,
        IReadOnlyCollection<string> codigosDelDirectorio)
    {
        var tokens = TokenizadorTexto.Tokenizar(pregunta);
        var porNombre = catalogo.Where(a => Aparece(tokens, a.Nombre)).Select(a => a.Codigo);
        var porCodigo = codigosDelDirectorio.Concat(catalogo.Select(a => a.Codigo)).Where(codigo => Aparece(tokens, codigo));
        return [.. porNombre.Concat(porCodigo).Select(AmbitoPersonal.Clave).Distinct(StringComparer.Ordinal)];
    }

    private static bool Aparece(IReadOnlyList<TokenTexto> tokens, string texto)
    {
        var secuencia = TokenizadorTexto.Valores(texto);
        return secuencia.Count > 0 && TokenizadorTexto.BuscarSecuencia(tokens, secuencia) >= 0;
    }
}
using System.Security.Cryptography;

namespace TutorFlow.Core.Asistente;

public sealed class ConfiguracionAsistente
{
    private const int BytesDelMarcadorAleatorio = 32;
    private const int TokensDeEntradaReservados = 8000;
    private const int TokensDeSalidaReservados = 2000;
    private const int MinimoPermitido = 1;

    public const int RelevanciaMinimaPorDefecto = 2;
    public const int ApoyoMinimoPorDefecto = 2;

    public ConfiguracionAsistente(
        PrecioModelo? precio,
        string? marcadorCanarioConfigurado,
        IReadOnlyCollection<string> codigosAsignatura,
        decimal? reservaPorPeticionUsd = null,
        int relevanciaMinima = RelevanciaMinimaPorDefecto,
        int apoyoMinimoRespaldo = ApoyoMinimoPorDefecto,
        IReadOnlyList<AsignaturaCatalogo>? catalogo = null)
    {
        Catalogo = catalogo is { Count: > 0 } ? catalogo : CatalogoAsignaturas.PorDefecto;
        Precio = precio;
        MarcadorCanario = string.IsNullOrWhiteSpace(marcadorCanarioConfigurado)
            ? Convert.ToHexString(RandomNumberGenerator.GetBytes(BytesDelMarcadorAleatorio))
            : marcadorCanarioConfigurado;
        CodigosAsignatura = codigosAsignatura;
        ReservaPorPeticionUsd = reservaPorPeticionUsd ?? ReservaPorDefecto(precio);
        RelevanciaMinima = Math.Max(MinimoPermitido, relevanciaMinima);
        ApoyoMinimoRespaldo = Math.Max(MinimoPermitido, apoyoMinimoRespaldo);
    }

    public PrecioModelo? Precio { get; }

    public string MarcadorCanario { get; }

    public IReadOnlyCollection<string> CodigosAsignatura { get; }

    public IReadOnlyList<AsignaturaCatalogo> Catalogo { get; }

    public decimal ReservaPorPeticionUsd { get; }

    public int RelevanciaMinima { get; }

