const entries = [];
for (let cp = 0xA0; cp <= 0x1FFFF; cp++) {
  if (cp >= 0xD800 && cp <= 0xDFFF) continue;
  const s = String.fromCodePoint(cp);
  const kd = s.normalize('NFKD');
  const d = s.normalize('NFD');
  if (kd === d) continue;
  const n = s.normalize('NFKC');
  const stripped = n.normalize('NFD').replace(/\p{M}/gu, '');
  if (!/^[\p{Script=Latin}\p{Nd}\p{N}\p{P}\p{S}\p{Z}]+$/u.test(stripped)) continue;
  if (!/[\p{L}\p{N}]/u.test(stripped)) continue;
  if (/^\p{Script=Latin}$/u.test(s) && false) continue;
  entries.push([cp, n]);
}
const sepOk = !entries.some(([, n]) => n.includes('|') || n.includes('\n') || n.includes('='));
console.error('entries', entries.length, 'sepOk', sepOk);
const runs = [];
for (const [cp, n] of entries) {
  const last = runs[runs.length - 1];
  if (last && last.start + last.t.length === cp) last.t.push(n);
  else runs.push({ start: cp, t: [n] });
}
for (const r of runs) {
  r.t.length;
}
const lines = runs.map(r => r.start.toString(16).toUpperCase() + '=' + r.t.join('|'));
console.error('runs', runs.length, 'chars', lines.join('\n').length);
require('fs').writeFileSync(process.argv[2], lines.join('\n'), 'utf8');

