        Conector + "(?:" + Seccion + ConectorHaciaDocumento + Documento
        + "|" + Documento + @"\s*[·,:-]\s*" + Seccion
        + "|" + Documento + ")";

    private static readonly TimeSpan LimiteRegex = TimeSpan.FromMilliseconds(LimiteRegexMs);

