using System.Text.RegularExpressions;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal sealed record TramoDePersona(string PersonaId, IReadOnlyList<TokenTexto> Tokens);

internal sealed record OracionAnalizada(string Texto, IReadOnlyList<TramoDePersona> Tramos);

internal static partial class TramosDePersonas
{
    private static readonly HashSet<string> PalabrasDelSujetoCoordinado = new(StringComparer.Ordinal) { "y", "e", "id" };

    public static IEnumerable<string> Oraciones(string respuesta) =>
        CorteDeOracion().Split(respuesta).Where(oracion => !string.IsNullOrWhiteSpace(oracion));

    public static IReadOnlyList<OracionAnalizada> DeRespuesta(
        string respuesta,
        Rol rol,
        IReadOnlyCollection<string> idsAutorizados,
        DirectorioAcademico directorio)
    {
        var herencia = new HerenciaEnListas(rol == Rol.Coordinador);
        return [.. SaltoDeLinea().Split(respuesta).SelectMany(linea =>
        {
            var persona = herencia.PersonaHeredada(linea, DetectorTerceros.MencionesDeAutorizados(linea, idsAutorizados, directorio));
            return persona is null
                ? Oraciones(linea).Select(oracion => new OracionAnalizada(oracion, De(oracion, idsAutorizados, directorio)))
                : [new OracionAnalizada(linea, [new TramoDePersona(persona, TokenizadorTexto.Tokenizar(linea))])];
        })];
    }

    public static IReadOnlyList<TramoDePersona> De(
        string oracion,
        IReadOnlyCollection<string> idsAutorizados,
        DirectorioAcademico directorio)
    {
        var menciones = DetectorTerceros.MencionesDeAutorizados(oracion, idsAutorizados, directorio);
        if (menciones.Count == 0)
        {
            return [];
        }

        var tokens = TokenizadorTexto.Tokenizar(oracion);
        var primeraDeCualquiera = menciones[0].Inicio;
        var tramos = menciones.GroupBy(mencion => mencion.Id)
            .Select(grupo => TramoDe(grupo.Key, grupo.First().Inicio, menciones, tokens, primeraDeCualquiera))
            .ToList();
        return Coordinar(tramos, menciones);
    }

    private static TramoDePersona TramoDe(
        string personaId,
        int inicio,
        IReadOnlyList<MencionDeAutorizado> menciones,
        IReadOnlyList<TokenTexto> tokens,
        int primeraDeCualquiera)
    {
        var fin = menciones
            .Where(mencion => mencion.Id != personaId && mencion.Inicio > inicio)
            .Select(mencion => mencion.Inicio)
            .DefaultIfEmpty(int.MaxValue)
            .Min();
        var delTramo = tokens.Where(token => token.Inicio < primeraDeCualquiera || (token.Inicio >= inicio && token.Inicio < fin));
        return new TramoDePersona(personaId, [.. delTramo]);
    }

    private static List<TramoDePersona> Coordinar(List<TramoDePersona> tramos, IReadOnlyList<MencionDeAutorizado> menciones)
    {
        for (var indice = tramos.Count - 2; indice >= 0; indice--)
        {
            if (ComparteElPredicado(tramos[indice], menciones))
            {
                var siguiente = tramos[indice + 1];
                var propios = siguiente.Tokens.Where(token => !EnMencion(token, siguiente.PersonaId, menciones));
                tramos[indice] = tramos[indice] with { Tokens = [.. tramos[indice].Tokens.Union(propios).OrderBy(token => token.Inicio)] };
            }
        }

        return tramos;
    }

    private static bool ComparteElPredicado(TramoDePersona tramo, IReadOnlyList<MencionDeAutorizado> menciones)
    {
        var primera = menciones.First(mencion => mencion.Id == tramo.PersonaId).Inicio;
        return tramo.Tokens
            .Where(token => token.Inicio >= primera && !EnMencion(token, tramo.PersonaId, menciones))
            .All(token => PalabrasDelSujetoCoordinado.Contains(token.Valor));
    }

    private static bool EnMencion(TokenTexto token, string personaId, IReadOnlyList<MencionDeAutorizado> menciones) =>
        menciones.Any(mencion => mencion.Id == personaId && token.Inicio >= mencion.Inicio && token.Inicio < mencion.Fin);

    [GeneratedRegex(@"\r?\n|(?<=[.!?;])(?=\s|$)", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex CorteDeOracion();

    [GeneratedRegex(@"\r?\n", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex SaltoDeLinea();

    private sealed partial class HerenciaEnListas(bool activa)
    {
        private string? _encabezado;
        private bool _enBloque;

        public string? PersonaHeredada(string linea, IReadOnlyList<MencionDeAutorizado> menciones)
        {
            if (!activa)
            {
                return null;
            }

            if (string.IsNullOrWhiteSpace(linea) || menciones.Count > 0)
            {
                _encabezado = menciones.Count > 0 ? menciones[^1].Id : null;
                _enBloque = false;
                return null;
            }

            _enBloque = _enBloque || (_encabezado is not null && MarcadorDeLista().IsMatch(linea));
            _encabezado = _enBloque ? _encabezado : null;
            return _encabezado;
        }

        [GeneratedRegex(@"^\s*(?:[-*•]|\d+[.)])\s", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
        private static partial Regex MarcadorDeLista();
    }
}

namespace TutorFlow.Core.Asistente;

internal sealed record FormaDePerdida(int Inicio, int Fin, bool Nominal, bool Negada, bool PorInasistencia);

internal static class FormasDePerdida
{
    private const int PalabrasDeNegacionPrevia = 2;
    private const string Ninguna = "ninguna";
    private const string PorInasistencia = "por";

    private static readonly HashSet<string> Palabras = new(StringComparer.Ordinal)
    {
        "perdi", "perdio", "perdiste", "perdieron", "perdido", "perdidos", "perdida", "perdidas"
    };

    private static readonly HashSet<string> Verbos = new(StringComparer.Ordinal)
    {
        "tiene", "tienen", "tengo", "tienes", "tener", "hay", "registra", "registran"
    };

    private static readonly HashSet<string> Determinantes = new(StringComparer.Ordinal)
    {
        "una", "unas", "alguna", "algunas", Ninguna, "sus", "dos", "tres", "cuatro"
    };

    private static readonly HashSet<string> Sustantivos = new(StringComparer.Ordinal)
    {
        "asignatura", "asignaturas", "materia", "materias"
    };

    private static readonly HashSet<string> Participios = new(StringComparer.Ordinal) { "perdida", "perdidas" };

    private static readonly HashSet<string> NegacionesPrevias = new(StringComparer.Ordinal)
    {
        "no", "ni", "sin", "ningun", Ninguna, "ninguno", "cero"
    };

    private static readonly HashSet<string> NegacionesPosteriores = new(StringComparer.Ordinal)
    {
        Ninguna, "ninguno", "ningun", "no", "cero", "0"
    };

    private static readonly HashSet<string> Inasistencias = new(StringComparer.Ordinal) { "inasistencia", "inasistencias" };

    public static IReadOnlyList<FormaDePerdida> En(IReadOnlyList<string> palabras) =>
        [.. Enumerable.Range(0, palabras.Count).Select(indice => FormaEn(palabras, indice)).OfType<FormaDePerdida>()];

    private static FormaDePerdida? FormaEn(IReadOnlyList<string> palabras, int indice)
    {
        if (EsNominal(palabras, indice))
        {
            return Nominal(palabras, indice);
        }

        return Palabras.Contains(palabras[indice]) ? Construir(palabras, indice, indice, nominal: false) : null;
    }

    private static bool EsNominal(IReadOnlyList<string> palabras, int indice) =>
        Participios.Contains(palabras[indice]) && indice > 0 && Sustantivos.Contains(palabras[indice - 1]);

    private static FormaDePerdida Nominal(IReadOnlyList<string> palabras, int indice)
    {
        var inicio = indice - 1;
        inicio -= inicio > 0 && Determinantes.Contains(palabras[inicio - 1]) ? 1 : 0;
        inicio -= inicio > 0 && Verbos.Contains(palabras[inicio - 1]) ? 1 : 0;
        return Construir(palabras, inicio, indice, nominal: true);
    }

    private static FormaDePerdida Construir(IReadOnlyList<string> palabras, int inicio, int fin, bool nominal) =>
        new(inicio, fin, nominal, EstaNegada(palabras, inicio, fin), nominal && SeguidaDePorInasistencia(palabras, fin));

    private static bool EstaNegada(IReadOnlyList<string> palabras, int inicio, int fin) =>
        palabras.Skip(Math.Max(0, inicio - PalabrasDeNegacionPrevia)).Take(Math.Min(PalabrasDeNegacionPrevia, inicio)).Any(NegacionesPrevias.Contains)
        || palabras.Skip(inicio).Take(fin - inicio + 1).Any(palabra => palabra == Ninguna && Determinantes.Contains(palabra) && palabra != palabras[fin])
        || (fin + 1 < palabras.Count && NegacionesPosteriores.Contains(palabras[fin + 1]));

    private static bool SeguidaDePorInasistencia(IReadOnlyList<string> palabras, int fin) =>
        fin + 2 < palabras.Count && palabras[fin + 1] == PorInasistencia && Inasistencias.Contains(palabras[fin + 2]);
}

